To implement custom middleware in Express.js, create a function that takes (req, res, next) and call next() to pass control to the next middleware:

```javascript
const express = require('express');
const app = express();

// Custom middleware - logs request details
app.use((req, res, next) => {
  console.log(`${req.method} ${req.url} - ${new Date().toISOString()}`);
  next();
});

// Middleware for authentication
app.use((req, res, next) => {
  const token = req.headers['authorization'];
  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }
  req.user = { id: 1, name: 'User' }; // decoded from token
  next();
});

// Middleware for specific routes
const validateInput = (req, res, next) => {
  if (!req.body.name) {
    return res.status(400).json({ error: 'Name is required' });
  }
  next();
};

app.post('/api/users', validateInput, (req, res) => {
  res.json({ message: 'User created' });
});

// Error-handling middleware (has 4 params)
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong' });
});

app.listen(3000);
```

Middleware runs in the order it's defined. Use next() to pass control, send a response to end the chain, or use error-handling middleware (4 parameters) to catch errors.
